def two_sum_quadratic(nums: list[int], target: int) -> list[int]:
    """Quadratic brute force O(n²) comparison."""
    n = len(nums)
    # Outer and inner loop checking every pair
    for i in range(n):
        for j in range(i + 1, n):
            if nums[i] + nums[j] == target:
                return [i, j]
    return []

