    void cancel_order(int order_id) {
        // Inefficient: O(n) scan + O(n) element shifting on erase
        for (auto it = buy_orders.begin(); it != buy_orders.end(); ++it) {
            if (it->id == order_id) {
                buy_orders.erase(it);
                return;
            }
